import java.util.*;

public class Solution {
    public boolean hasCycle(ListNode head) {
        Set<ListNode> seen = new HashSet<>();
        ListNode p = head;
        while (p != null) {
            // 同一个节点被访问第二次，说明绕回来了
            if (!seen.add(p)) return true;
            p = p.next;
        }
        return false;
    }
}

public class Solution {
    public boolean hasCycle(ListNode head) {
        if (head == null || head.next == null) return false;

        ListNode slow = head, fast = head;
        // 两个条件都要判：fast 要连走两步
        while (fast != null && fast.next != null) {
            slow = slow.next;        // 一步
            fast = fast.next.next;   // 两步
            if (slow == fast) return true;   // 相遇即有环
        }
        return false;
    }
}

public class Solution {
    public boolean hasCycle(ListNode head) {
        if (head == null || head.next == null) return false;

        // 快指针先走一步，避免第一轮 slow == fast 的无效比较
        ListNode slow = head;
        ListNode fast = head.next;

        while (fast != null && fast.next != null) {
            if (slow == fast) return true;
            slow = slow.next;
            fast = fast.next.next;
        }
        return false;
    }
}
